"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["62218"],{17145(e,t,n){n.r(t),n.d(t,{metadata:()=>r,default:()=>g,frontMatter:()=>c,contentTitle:()=>h,toc:()=>d,assets:()=>u});var r=JSON.parse('{"id":"nhcx/v1/api/other/endpoints/other-swagger-resources-configuration-security","title":"Get the swagger security configuration","description":"Returns the Swagger UI security configuration for the status service; consumed by Swagger UI, not by integrations.","source":"@site/docs/nhcx/v1/api/other/endpoints/other-swagger-resources-configuration-security.mdx","sourceDirName":"nhcx/v1/api/other/endpoints","slug":"/nhcx/v1/api/other/endpoints/other-swagger-resources-configuration-security","permalink":"/docs/pr-14/docs/nhcx/v1/api/other/endpoints/other-swagger-resources-configuration-security","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Get the swagger security configuration","sidebar_label":"Get the swagger security configuration","sidebar_class_name":"api-method api-method--get","description":"Returns the Swagger UI security configuration for the status service; consumed by Swagger UI, not by integrations.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","source":"nhcx-other.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Get the swagger UI configuration","permalink":"/docs/pr-14/docs/nhcx/v1/api/other/endpoints/other-swagger-resources-configuration-ui"},"next":{"title":"Submit the status callback","permalink":"/docs/pr-14/docs/nhcx/v1/api/other/endpoints/other-v1-on-status"}}'),s=n(62540),a=n(43023),o=n(75064),i=JSON.parse('{"id":"other_swagger_resources_configuration_security","module":"Other","moduleId":"other","kind":"operation","method":"GET","path":"/swagger-resources/configuration/security","server":"https://apisbx.abdm.gov.in/hcx","servers":[{"url":"https://apisbx.abdm.gov.in/hcx","description":"Sandbox, NHCX exchange."},{"url":"https://apisprod.nha.gov.in/hcx","description":"Production."}],"summary":"Swagger security configuration","title":"Get the swagger security configuration","description":"Returns the Swagger UI security configuration for the status service; consumed by Swagger UI, not by integrations.\\n\\n### Business purpose\\n\\nSwagger UI reads this endpoint to learn how to present authorisation inputs (such as a bearer token field) when a user tries operations from the browser. It describes UI behaviour only; it does not issue tokens, and it is unrelated to the client-credentials flow at /get/session or to the JWE encryption that protects protocol payloads. The endpoint index describes it as the Swagger security configuration.\\n\\n### When to use\\n\\nUse it only in a Swagger UI session against the status service; integrations never need it. The endpoint index lists it as endpoint 23. It is not part of any transaction workflow, not a source of credentials, and not referenced by the sandbox exit checklists.\\n\\n### Preconditions\\n\\n- A GET request to the status service host; the OpenAPI documents in this corpus were captured from https://hcxsbx.ABDM.gov.in/<service>/api-docs, and the status service declares the server prefix /statushcxservice.\\n- No JWE envelope, no x-hcx-* protocol headers and no correlation ID; the docs do not state that a Bearer token is required for these discovery endpoints.\\n- No request body.\\n\\n### Postconditions\\n\\nThe service returns HTTP 200 with a small JSON object describing how Swagger UI should handle security inputs. Nothing changes on NHCX, no token is issued and no callback follows. The documentation does not enumerate the fields, so the example below is illustrative.\\n\\n### Common mistakes\\n\\n- Pointing at the gateway base https://apisbx.ABDM.gov.in/pmjay/sbxhcx and expecting the per-service spec host; the docs advise swapping between the two URL shapes when a path 404s.\\n- Treating the served document as the integration contract for gateway traffic; the handbook\'s gateway base and header conventions take precedence where the two disagree.\\n- Sending a POST or a JSON body to a GET discovery endpoint.\\n- Wrapping the call in JWE or adding x-hcx-* headers, which only apply to protocol APIs such as /v1/status.\\n- Mistaking this endpoint for an authentication API; tokens come only from the client-credentials call documented in the authentication chapter.\\n\\n### Best practices\\n\\n- Use these endpoints for exploration and client generation in the sandbox, and cache the document rather than fetching it on every run.\\n- Diff the served document against the corpus (Status service: OpenAPI 3.0.1, version 1.0.0) when behaviour changes unexpectedly.\\n- Never let production traffic depend on the availability of the documentation endpoints.\\n- Keep the /v1/status protocol rules in mind when reading the spec: x-hcx-correlation_ID must carry the original request\'s correlation ID.\\n\\n### Related scenario\\n\\nA provider\'s engineer wants to try /v1/status from Swagger UI in the sandbox. The UI fetches /swagger-resources/configuration/security to decide how to show the authorisation dialog, and the engineer pastes a Bearer token obtained separately from the client-credentials call. Because the status request body must be a JWE built with the payer\'s certificate, the engineer ultimately uses the UI only to confirm the schema and runs the real status request from the integration code, which reuses the original preauth correlation ID.\\n\\n### Specification\\n\\nChapter [Environments and addresses](/docs/nhcx/v1/reference/environments-and-addresses) of the NHCX integration specification.","security":[{"name":"bearerAuth","type":"http","scheme":"bearer","description":"On every NHCX call, the token goes in a header called `bearer_auth`, with the word `Bearer` and a space in front. The sources are not unanimous: the authentication page and the FAQ both write the example as `Authorization`, and the notification endpoint uses `Authorization`. The safe course, and what the adapter does, is to send both headers with the same value."}],"headers":[{"name":"bearer_auth","required":true,"description":"It is `bearer_auth`, not `Authorization`, on NHCX\'s own endpoints.","example":"Bearer <access token>","type":"string"}],"pathParams":[],"queryParams":[],"body":[],"responses":[{"status":"200","description":"The service returns HTTP 200 with a small JSON object describing how Swagger UI should handle security inputs.","example":{"apiKeyVehicle":"header","apiKeyName":"bearer_auth","scopeSeparator":","}}],"tag":"Other operations","curl":"curl --request GET \\\\\\n  --url https://apisbx.abdm.gov.in/hcx/swagger-resources/configuration/security \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\'","samples":[{"id":"curl","label":"cURL","language":"bash","code":"curl --request GET \\\\\\n  --url https://apisbx.abdm.gov.in/hcx/swagger-resources/configuration/security \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\'"},{"id":"python","label":"Python","language":"python","code":"import requests\\n\\nresponse = requests.get(\\n    \\"https://apisbx.abdm.gov.in/hcx/swagger-resources/configuration/security\\",\\n    headers={\\n        \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n        \\"bearer_auth\\": \\"Bearer <access token>\\",\\n    },\\n)\\n\\nprint(response.status_code, response.text)"},{"id":"node","label":"Node","language":"javascript","code":"const response = await fetch(\\"https://apisbx.abdm.gov.in/hcx/swagger-resources/configuration/security\\", {\\n  method: \\"GET\\",\\n  headers: {\\n    \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n    \\"bearer_auth\\": \\"Bearer <access token>\\",\\n  },\\n});\\n\\nconsole.log(response.status, await response.text());"}]}');let c={title:"Get the swagger security configuration",sidebar_label:"Get the swagger security configuration",sidebar_class_name:"api-method api-method--get",description:"Returns the Swagger UI security configuration for the status service; consumed by Swagger UI, not by integrations.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",source:"nhcx-other.yaml",generated:!0},h,u={},d=[];function p(e){return(0,s.jsx)(o.A,{operation:i})}function g(e={}){let{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(p,{...e})}):p(e)}}}]);